package cn.zhuatech.meetingai.service; import jakarta.validation.constraints.*; import org.springframework.stereotype.Service; import java.util.*; /**
                                                                                                                                                    * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                    */
@Service public class MeetingActionService { /**
                                                                                                                                                                                                 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                 */
public record Request(@NotBlank String meetingTitle,@NotBlank String transcript,@Min(1) int attendeeCount,@Min(0) int openDecisions){} /**
                                                                                                                                                                                                                                                                                                                                        * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                        */
public record Result(String meetingTitle,String summary,List<String> actionItems,List<String> riskFlags,int confidence){} /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
public Result analyze(Request r){var actions=new ArrayList<String>();for(String s:r.transcript().split("[。；;\n]"))if(s.contains("负责")||s.contains("截止")||s.contains("完成"))actions.add(s.trim());if(actions.isEmpty())actions.add("请主持人补充负责人和截止日期");var risks=new ArrayList<String>();if(r.openDecisions()>0)risks.add("存在 "+r.openDecisions()+" 项未确认决议");if(r.attendeeCount()>15)risks.add("参会人数较多，建议分组确认行动项");return new Result(r.meetingTitle(),r.transcript().substring(0,Math.min(120,r.transcript().length())),actions,risks,Math.min(96,70+r.transcript().length()/20));} }
